<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Template\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\Template\Application\Service\Visibility\TemplateVisibilityService;
use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateVisibilityService $visibility,
        private readonly TemplateWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Template");
        $span = $this->startSpan("Check allow of create usecase for Template");
        try {
            $result = $this->dispatcher->dispatch(new TemplateCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(TemplateCreateParams $params): TemplateCreateResult
    {
        $this->logDebug("Run create usecase for Template");
        $span = $this->startSpan("Run create usecase for Template");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Template');
            }
            $this->dispatcher->dispatch(new TemplateCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new TemplateCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = Template::create($input);
            $result = $this->writer->create(
                $entity,
                fn (Template $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
